    "walletSetup.phraseKeychain": ["\u042D\u0442\u043E \u0433\u043B\u0430\u0432\u043D\u0430\u044F \u0444\u0440\u0430\u0437\u0430 Tonkeeper. \u041D\u0443\u0436\u043D\u0430 \u0444\u0440\u0430\u0437\u0430 \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430: \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u2192 \u0420\u0435\u0437\u0435\u0440\u0432\u043D\u0430\u044F \u043A\u043E\u043F\u0438\u044F", "This is Tonkeeper\u2019s main phrase. Use the account phrase: Settings \u2192 Backup", "\u0426\u0435 \u0433\u043E\u043B\u043E\u0432\u043D\u0430 \u0444\u0440\u0430\u0437\u0430 Tonkeeper. \u041F\u043E\u0442\u0440\u0456\u0431\u043D\u0430 \u0444\u0440\u0430\u0437\u0430 \u0430\u043A\u0430\u0443\u043D\u0442\u0430: \u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u2192 \u0420\u0435\u0437\u0435\u0440\u0432\u043D\u0430 \u043A\u043E\u043F\u0456\u044F", "\u0411\u04B1\u043B Tonkeeper-\u0434\u0456\u04A3 \u0431\u0430\u0441\u0442\u044B \u0444\u0440\u0430\u0437\u0430\u0441\u044B. \u0410\u043A\u043A\u0430\u0443\u043D\u0442 \u0444\u0440\u0430\u0437\u0430\u0441\u044B \u043A\u0435\u0440\u0435\u043A: \u0411\u0430\u043F\u0442\u0430\u0443\u043B\u0430\u0440 \u2192 \u0421\u0430\u049B\u0442\u044B\u049B \u043A\u04E9\u0448\u0456\u0440\u043C\u0435"],
