    "orders.takeFar": ["\u0422\u0435\u0439\u043A \u0441\u043B\u0438\u0448\u043A\u043E\u043C \u0434\u0430\u043B\u0435\u043A\u043E \u043E\u0442 \u0446\u0435\u043D\u044B", "The take-profit is too far from the price", "\u0422\u0435\u0439\u043A \u043D\u0430\u0434\u0442\u043E \u0434\u0430\u043B\u0435\u043A\u043E \u0432\u0456\u0434 \u0446\u0456\u043D\u0438", "\u0422\u0435\u0439\u043A \u0431\u0430\u0493\u0430\u0434\u0430\u043D \u0442\u044B\u043C \u0430\u043B\u044B\u0441"],
