    "orders.failedHere": ["\u041D\u0435 \u043F\u0440\u043E\u0448\u0451\u043B \xB7 \u0442\u043E\u043A\u0435\u043D\u044B \u043D\u0430 \u043E\u0440\u0434\u0435\u0440\u0435", "Failed \xB7 tokens on the order", "\u041D\u0435 \u043F\u0440\u043E\u0439\u0448\u043E\u0432 \xB7 \u0442\u043E\u043A\u0435\u043D\u0438 \u043D\u0430 \u043E\u0440\u0434\u0435\u0440\u0456", "\u04E8\u0442\u043F\u0435\u0434\u0456 \xB7 \u0442\u043E\u043A\u0435\u043D\u0434\u0435\u0440 \u043E\u0440\u0434\u0435\u0440\u0434\u0435"],
    "orders.foundHere": ["\u041D\u0430\u0439\u0434\u0435\u043D\u043E \xB7 \u0442\u043E\u043A\u0435\u043D\u044B \u043D\u0430 \u043E\u0440\u0434\u0435\u0440\u0435", "Found \xB7 tokens on the order", "\u0417\u043D\u0430\u0439\u0434\u0435\u043D\u043E \xB7 \u0442\u043E\u043A\u0435\u043D\u0438 \u043D\u0430 \u043E\u0440\u0434\u0435\u0440\u0456", "\u0422\u0430\u0431\u044B\u043B\u0434\u044B \xB7 \u0442\u043E\u043A\u0435\u043D\u0434\u0435\u0440 \u043E\u0440\u0434\u0435\u0440\u0434\u0435"],

