    "wallets.legacyAnd": [" \u0438 ", " and ", " \u0456 ", " \u0436\u04D9\u043D\u0435 "],
    "wallets.legacyWhere": ["\u041F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0435\u043D\u043E\u0441\u0430 \u0434\u0435\u043D\u044C\u0433\u0438 \u0431\u0443\u0434\u0443\u0442 \u0437\u0434\u0435\u0441\u044C \u0438 \u0432 W5 \u0432 Tonkeeper", "After the move: here, and on W5 in Tonkeeper", "\u041F\u0456\u0441\u043B\u044F \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0435\u043D\u043D\u044F \u0433\u0440\u043E\u0448\u0456 \u0431\u0443\u0434\u0443\u0442\u044C \u0442\u0443\u0442 \u0456 \u0432 W5 \u0443 Tonkeeper", "\u041A\u04E9\u0448\u0456\u0440\u0433\u0435\u043D\u043D\u0435\u043D \u043A\u0435\u0439\u0456\u043D: \u043E\u0441\u044B\u043D\u0434\u0430 \u0436\u04D9\u043D\u0435 Tonkeeper-\u0434\u0435\u0433\u0456 W5-\u0442\u0435"],
    "wallets.legacyMove": ["\u041F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438", "Move", "\u041F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438", "\u041A\u04E9\u0448\u0456\u0440\u0443"],
