    "wallets.solAltLeft": ["\u041E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u043D\u0430 \u0441\u0442\u0430\u0440\u043E\u043C \u0430\u0434\u0440\u0435\u0441\u0435: {list}", "Still on the old address: {list}", "\u041B\u0438\u0448\u0438\u043B\u043E\u0441\u044F \u043D\u0430 \u0441\u0442\u0430\u0440\u0456\u0439 \u0430\u0434\u0440\u0435\u0441\u0456: {list}", "\u0415\u0441\u043A\u0456 \u043C\u0435\u043A\u0435\u043D\u0436\u0430\u0439\u0434\u0430 \u049B\u0430\u043B\u0434\u044B: {list}"],
    "wallets.solAltGas": ["\u041D\u0443\u0436\u043D\u043E {need} SOL \u043D\u0430 \u0441\u0442\u0430\u0440\u044B\u0439 \u0430\u0434\u0440\u0435\u0441. \u041F\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \xAB\u041F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438\xBB", "The old address needs {need} SOL. Top it up and tap \u201CMove\u201D", "\u041F\u043E\u0442\u0440\u0456\u0431\u043D\u043E {need} SOL \u043D\u0430 \u0441\u0442\u0430\u0440\u0443 \u0430\u0434\u0440\u0435\u0441\u0443. \u041F\u043E\u043F\u043E\u0432\u043D\u0456\u0442\u044C \u0456 \u043D\u0430\u0442\u0438\u0441\u043D\u0456\u0442\u044C \xAB\u041F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438\xBB", "\u0415\u0441\u043A\u0456 \u043C\u0435\u043A\u0435\u043D\u0436\u0430\u0439\u0493\u0430 {need} SOL \u043A\u0435\u0440\u0435\u043A. \u0422\u043E\u043B\u0442\u044B\u0440\u044B\u043F, \xAB\u041A\u04E9\u0448\u0456\u0440\u0443\xBB \u0431\u0430\u0441\u044B\u04A3\u044B\u0437"],
    "wallets.solAltFail": ["\u041D\u0435 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u043B\u043E\u0441\u044C, \u0434\u0435\u043D\u044C\u0433\u0438 \u043D\u0430 \u0441\u0442\u0430\u0440\u043E\u043C \u0430\u0434\u0440\u0435\u0441\u0435", "Move failed, money stays on the old address", "\u041D\u0435 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u043B\u043E\u0441\u044F, \u0433\u0440\u043E\u0448\u0456 \u043D\u0430 \u0441\u0442\u0430\u0440\u0456\u0439 \u0430\u0434\u0440\u0435\u0441\u0456", "\u041A\u04E9\u0448\u043F\u0435\u0434\u0456, \u0430\u049B\u0448\u0430 \u0435\u0441\u043A\u0456 \u043C\u0435\u043A\u0435\u043D\u0436\u0430\u0439\u0434\u0430"],
    "wallets.solAltUnknown": ["\u0421\u0442\u0430\u0440\u044B\u0439 \u0430\u0434\u0440\u0435\u0441 \u043D\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D, \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u0437\u0436\u0435", "Old address unchecked, try later", "\u0421\u0442\u0430\u0440\u0443 \u0430\u0434\u0440\u0435\u0441\u0443 \u043D\u0435 \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u0435\u043D\u043E, \u0441\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u043F\u0456\u0437\u043D\u0456\u0448\u0435", "\u0415\u0441\u043A\u0456 \u043C\u0435\u043A\u0435\u043D\u0436\u0430\u0439 \u0442\u0435\u043A\u0441\u0435\u0440\u0456\u043B\u043C\u0435\u0434\u0456, \u043A\u0435\u0439\u0456\u043D\u0456\u0440\u0435\u043A \u049B\u0430\u0439\u0442\u0430\u043B\u0430\u04A3\u044B\u0437"],
    "wallets.solAltTrust": ["\u041E\u0442\u0441\u044E\u0434\u0430 \u043D\u0435 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438, \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 Trust Wallet", "Can\u2019t move from here, try Trust Wallet", "\u0417\u0432\u0456\u0434\u0441\u0438 \u043D\u0435 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438, \u0441\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 Trust Wallet", "\u041C\u04B1\u043D\u0434\u0430 \u043A\u04E9\u0448\u0456\u0440\u0443 \u043C\u04AF\u043C\u043A\u0456\u043D \u0435\u043C\u0435\u0441, Trust Wallet-\u0442\u0456 \u043A\u04E9\u0440\u0456\u04A3\u0456\u0437"],
    "wallets.solAltStuck": ["\u041E\u0442\u0441\u044E\u0434\u0430 \u043D\u0435 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438", "Can\u2019t move from here", "\u0417\u0432\u0456\u0434\u0441\u0438 \u043D\u0435 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438", "\u041C\u04B1\u043D\u0434\u0430 \u043A\u04E9\u0448\u0456\u0440\u0443 \u043C\u04AF\u043C\u043A\u0456\u043D \u0435\u043C\u0435\u0441"],
    "wallets.solAltKept": ["\u0427\u0430\u0441\u0442\u044C \u0442\u043E\u043A\u0435\u043D\u043E\u0432 \u043D\u0430 \u0441\u0442\u0430\u0440\u043E\u043C \u0430\u0434\u0440\u0435\u0441\u0435, \u0442\u0430\u043C \u043E\u0441\u0442\u0430\u0432\u043B\u0435\u043D SOL \u043D\u0430 \u043F\u0435\u0440\u0435\u0432\u043E\u0434", "Some tokens stay on the old address, with SOL left to move them", "\u0427\u0430\u0441\u0442\u0438\u043D\u0430 \u0442\u043E\u043A\u0435\u043D\u0456\u0432 \u043D\u0430 \u0441\u0442\u0430\u0440\u0456\u0439 \u0430\u0434\u0440\u0435\u0441\u0456, \u0442\u0430\u043C \u043B\u0438\u0448\u0435\u043D\u043E SOL \u043D\u0430 \u043F\u0435\u0440\u0435\u043A\u0430\u0437", "\u041A\u0435\u0439\u0431\u0456\u0440 \u0442\u043E\u043A\u0435\u043D\u0434\u0435\u0440 \u0435\u0441\u043A\u0456 \u043C\u0435\u043A\u0435\u043D\u0436\u0430\u0439\u0434\u0430, \u0430\u0443\u0434\u0430\u0440\u0443\u0493\u0430 SOL \u049B\u0430\u043B\u0434\u044B\u0440\u044B\u043B\u0434\u044B"],
